<script setup>
import {ref,computed,onBeforeUnmount} from 'vue';
import {Button,Cell,CellGroup,Field,Slider,Popup,Picker,Collapse,CollapseItem} from 'vant';
import 'vant/es/slider/style';
const {controller}=defineProps({controller:{type:Object,required:true}}),m=ref(controller.model),a=controller.actions;
