const picker=ref(''),selection=ref([]),about=ref(false),expanded=ref([]),error=ref('');
const geometry=computed(()=>m.value.kind==='geometry');
const columns=computed(()=>picker.value==='chapter'?m.value.chapters.map(c=>({text:`${c.term==='upper'?'上册':'下册'} · 第${c.number}章 ${c.title}`,value:c.id})):picker.value==='animate'?m.value.current.controls.map(c=>({text:c.label,value:c.key})):picker.value==='speed'?[.5,1,2].map(v=>({text:v+'×',value:v})):picker.value==='group'?[{text:'全部类别',value:''},...m.value.groups.map(v=>({text:v,value:v}))]:[{text:'全部模型',value:''},{text:'八年级基础与综合',value:'core'},{text:'含后续课程的拓展',value:'advanced'}]);
function open(key){picker.value=key;selection.value=[key==='chapter'?m.value.chapter.id:key==='animate'?m.value.animateKey:key==='speed'?m.value.speed:m.value.filters[key]];}
function picked({selectedValues}){const key=picker.value,v=selectedValues[0];picker.value='';if(['group','level'].includes(key))a.filter(key,v);else a[key==='animate'?'animate':key](v);}
function act(name,...args){try{error.value='';a[name](...args);}catch(e){error.value=e.message;}}
function sliderKey(event,control){if(!['ArrowLeft','ArrowDown','ArrowRight','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const value=control?m.value.values[control.key]:m.value.progress,min=control?.min??0,max=control?.max??3,step=control?.step??.01,next=event.key==='Home'?min:event.key==='End'?max:value+(['ArrowLeft','ArrowDown'].includes(event.key)?-step:step);if(control)act('adjust',control.key,next);else act('progress',next);}
</script>
<template>
 <main class="student-math-labs" :data-lab-kind="m.kind">
 <template v-if="!geometry">
  <header class="top"><div><p class="eyebrow">MATH / EXPLORE &amp; UNDERSTAND</p><h1>动手，让数学看得见</h1></div><nav class="tools"><Button tag="a" :href="m.backHref">← 回到本章课堂</Button><Button @click="a.fullscreen">全屏</Button><Button @click="about=true">说明</Button></nav></header>
